//! The committed `bulk-write-categorization` oracle.
//!
//! `testdata/vectors/bulk-write-categorization.json` is lane C's family (47 cases),
//! generated by running upstream's `categorizeBulkWriteRows`
//! (`src/rx-storage-helper.ts:205`) at pin `3b763ee17` in Node. It is the *committed*
//! oracle for that function, and this test is what consumes it.
//!
//! It complements, rather than replaces, `tests/categorize_oracle.rs`: that file runs a
//! 600-case randomised corpus (also from upstream, marked ADDITIONAL in its header)
//! which reaches combinations no curator writes down — 318 of its cases produce errors
//! and 466 batch several rows against one document snapshot. This family documents the
//! *rules*, one case per rule, with names a reviewer can read. Both are checked.
//!
//! The mapping from the vector's shape to this crate's API is deliberately literal so a
//! reviewer can diff it against `src/rx-storage-helper.ts`:
//!
//! | vector field | this crate |
//! | --- | --- |
//! | `docsInDb` (object keyed by id) | a `HashMap<String, DocumentData>` |
//! | `writeRows` | `Vec<BulkWriteRow>` |
//! | `bulkInsertDocs` | `output.bulk_insert_docs` |
//! | `bulkUpdateDocs` | `output.bulk_update_docs` |
//! | `newestRow` | `output.checkpoint` (same source: the last written row) |
//! | `errors` | `output.error` |
//! | `events` | `output.events` |
//! | `eventBulk.context` | the `context` passed through |
//! | `attachments{Add,Remove,Update}` | the same three fields |

use std::collections::HashMap;

use dxdb_storage::{
    categorize_bulk_write_rows, AttachmentData, AttachmentWriteData, BulkWriteRow, DocumentData,
    DocumentWriteData, Operation,
};
use serde::Deserialize;
use serde_json::Value;

#[derive(Debug, Deserialize)]
struct Family {
    /// The primary key path every case in the family uses.
    #[serde(rename = "primaryPath")]
    primary_path: String,
    #[serde(rename = "caseCount")]
    case_count: usize,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    schema: String,
    why: String,
    context: String,
    #[serde(rename = "docsInDb")]
    docs_in_db: Value,
    #[serde(rename = "writeRows")]
    write_rows: Vec<RowJson>,
    #[serde(rename = "bulkInsertDocs", default)]
    bulk_insert_docs: Vec<RowJson>,
    #[serde(rename = "bulkUpdateDocs", default)]
    bulk_update_docs: Vec<RowJson>,
    #[serde(rename = "newestRow", default)]
    newest_row: Value,
    #[serde(default)]
    errors: Vec<ErrorJson>,
    #[serde(default)]
    events: Vec<EventJson>,
    #[serde(rename = "eventBulk")]
    event_bulk: Value,
    #[serde(rename = "attachmentsAdd", default)]
    attachments_add: Vec<AttachmentJson>,
    #[serde(rename = "attachmentsRemove", default)]
    attachments_remove: Vec<AttachmentJson>,
    #[serde(rename = "attachmentsUpdate", default)]
    attachments_update: Vec<AttachmentJson>,
}

#[derive(Debug, Deserialize)]
struct RowJson {
    #[serde(default)]
    previous: Option<Value>,
    document: Value,
}

#[derive(Debug, Deserialize)]
struct ErrorJson {
    #[serde(rename = "documentId")]
    document_id: String,
    status: u16,
    #[serde(rename = "attachmentId", default)]
    attachment_id: Option<String>,
}

#[derive(Debug, Deserialize)]
struct EventJson {
    #[serde(rename = "documentId")]
    document_id: String,
    operation: String,
    #[serde(rename = "previousDocumentData", default)]
    previous_document_data: Value,
    #[serde(rename = "documentData")]
    document_data: Value,
}

#[derive(Debug, Deserialize)]
struct AttachmentJson {
    #[serde(rename = "documentId")]
    document_id: String,
    #[serde(rename = "attachmentId")]
    attachment_id: String,
    digest: String,
}

fn load() -> Family {
    let path = format!(
        "{}/../../testdata/vectors/bulk-write-categorization.json",
        env!("CARGO_MANIFEST_DIR")
    );
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("read {path}: {error}; run `make vectors`"));
    let family: Family = serde_json::from_str(&text)
        .unwrap_or_else(|error| panic!("parse {path}: {error}"));
    assert_eq!(
        family.cases.len(),
        family.case_count,
        "caseCount disagrees with cases"
    );
    family
}

/// Builds a write row from the vector's shape.
///
/// A supplied attachment payload is recorded by the generator as a `data` member whose
/// value is a stable marker; any stub without one is "metadata only", which is the case
/// upstream treats as missing data.
fn to_write_data(document: &Value) -> DocumentWriteData {
    let mut stubs = Vec::new();
    let mut payloads = std::collections::BTreeMap::new();
    if let Some(attachments) = document.get("_attachments").and_then(Value::as_object) {
        for (attachment_id, stub) in attachments {
            let Some(object) = stub.as_object() else {
                continue;
            };
            stubs.push((
                attachment_id.clone(),
                AttachmentData {
                    length: object.get("length").and_then(Value::as_u64).unwrap_or(0),
                    content_type: object
                        .get("type")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_string(),
                    digest: object
                        .get("digest")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_string(),
                },
                object.get("data").cloned(),
            ));
        }
    }
    let mut data = DocumentData::from_value(document.clone()).expect("document is an object");
    // Rebuild through the typed path so the write looks like a real caller's.
    data.set("_attachments", Value::Object(Default::default()));
    let mut write = DocumentWriteData::new(data);
    for (attachment_id, stub, payload) in stubs {
        if let Some(payload) = payload {
            payloads.insert(attachment_id.clone(), serde_json::to_vec(&payload).expect("json"));
        }
        write.insert_attachment(
            &attachment_id,
            AttachmentWriteData {
                stub,
                data: payloads.remove(&attachment_id),
            },
        );
    }
    write
}

fn to_row(row: &RowJson) -> BulkWriteRow {
    BulkWriteRow {
        previous: row
            .previous
            .as_ref()
            .map(|value| DocumentData::from_value(value.clone()).expect("previous is an object")),
        document: to_write_data(&row.document),
    }
}

/// One case's expected output, reduced to what is observable.
#[derive(Debug, PartialEq)]
struct Observed {
    insert_ids: Vec<String>,
    update_ids: Vec<String>,
    errors: Vec<(String, u16, Option<String>)>,
    events: Vec<(String, String, bool, bool)>,
    checkpoint: Option<(String, f64)>,
    context: String,
    attachments_add: Vec<(String, String, String)>,
    attachments_remove: Vec<(String, String, String)>,
    attachments_update: Vec<(String, String, String)>,
}

fn expected_of(case: &Case) -> Observed {
    let ids = |rows: &[RowJson]| -> Vec<String> {
        rows.iter()
            .map(|row| {
                row.document
                    .get("passportId")
                    .or_else(|| row.document.get("id"))
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_string()
            })
            .collect()
    };
    Observed {
        insert_ids: ids(&case.bulk_insert_docs),
        update_ids: ids(&case.bulk_update_docs),
        errors: case
            .errors
            .iter()
            .map(|error| {
                (
                    error.document_id.clone(),
                    error.status,
                    error.attachment_id.clone(),
                )
            })
            .collect(),
        events: case
            .events
            .iter()
            .map(|event| {
                (
                    event.document_id.clone(),
                    event.operation.clone(),
                    !event.previous_document_data.is_null(),
                    event
                        .document_data
                        .get("_deleted")
                        .and_then(Value::as_bool)
                        .unwrap_or(false),
                )
            })
            .collect(),
        checkpoint: case
            .newest_row
            .get("passportId")
            .or_else(|| case.newest_row.get("id"))
            .and_then(Value::as_str)
            .map(|id| {
                let lwt = case
                    .newest_row
                    .get("_meta")
                    .and_then(|meta| meta.get("lwt"))
                    .and_then(Value::as_f64)
                    .unwrap_or(0.0);
                (id.to_string(), lwt)
            }),
        context: case
            .event_bulk
            .get("context")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        attachments_add: triple(&case.attachments_add),
        attachments_remove: triple(&case.attachments_remove),
        attachments_update: triple(&case.attachments_update),
    }
}

fn triple(items: &[AttachmentJson]) -> Vec<(String, String, String)> {
    items
        .iter()
        .map(|item| {
            (
                item.document_id.clone(),
                item.attachment_id.clone(),
                item.digest.clone(),
            )
        })
        .collect()
}

fn observed_of(family: &Family, case: &Case) -> Observed {
    let docs_in_db: HashMap<String, DocumentData> = case
        .docs_in_db
        .as_object()
        .map(|map| {
            map.iter()
                .map(|(id, document)| {
                    (
                        id.clone(),
                        DocumentData::from_value(document.clone()).expect("stored document"),
                    )
                })
                .collect()
        })
        .unwrap_or_default();
    let rows: Vec<BulkWriteRow> = case.write_rows.iter().map(to_row).collect();

    // The vector's own schema name tells us only whether attachments are declared; the
    // `human` fixtures have none and the attachment cases say so in their name.
    let has_attachments = case.schema.contains("attachment")
        || !case.attachments_add.is_empty()
        || !case.attachments_remove.is_empty()
        || !case.attachments_update.is_empty();

    let output = categorize_bulk_write_rows(
        &family.primary_path,
        &docs_in_db,
        &rows,
        &case.context,
        has_attachments,
    );

    let id_of = |document: &DocumentData| -> String {
        document
            .id(&family.primary_path)
            .map(str::to_string)
            .unwrap_or_default()
    };

    Observed {
        insert_ids: output
            .bulk_insert_docs
            .iter()
            .map(|row| id_of(&row.document))
            .collect(),
        update_ids: output
            .bulk_update_docs
            .iter()
            .map(|row| id_of(&row.document))
            .collect(),
        errors: output
            .error
            .iter()
            .map(|error| {
                let attachment_id = match error {
                    dxdb_storage::WriteError::Attachment { attachment_id, .. } => {
                        Some(attachment_id.clone())
                    }
                    _ => None,
                };
                (error.document_id().to_string(), error.status(), attachment_id)
            })
            .collect(),
        events: output
            .events
            .iter()
            .map(|event| {
                (
                    event.document_id.clone(),
                    event.operation.as_str().to_string(),
                    event.previous_document_data.is_some(),
                    event.document_data.is_deleted(),
                )
            })
            .collect(),
        checkpoint: output
            .checkpoint
            .as_ref()
            .map(|checkpoint| (checkpoint.id.clone(), checkpoint.lwt)),
        context: case.context.clone(),
        attachments_add: output
            .attachments_add
            .iter()
            .map(|add| {
                (
                    add.document_id.clone(),
                    add.attachment_id.clone(),
                    add.digest.clone(),
                )
            })
            .collect(),
        attachments_remove: output
            .attachments_remove
            .iter()
            .map(|remove| {
                (
                    remove.document_id.clone(),
                    remove.attachment_id.clone(),
                    remove.digest.clone(),
                )
            })
            .collect(),
        attachments_update: output
            .attachments_update
            .iter()
            .map(|update| {
                (
                    update.document_id.clone(),
                    update.attachment_id.clone(),
                    update.digest.clone(),
                )
            })
            .collect(),
    }
}

/// The whole committed family, case by case. A failure names the case.
#[test]
fn matches_the_committed_bulk_write_categorization_family() {
    let family = load();
    let mut failures = Vec::new();
    for case in &family.cases {
        let expected = expected_of(case);
        let observed = observed_of(&family, case);
        if expected != observed {
            // Report field by field, so a reviewer sees the rule that broke.
            let mut detail = Vec::new();
            if expected.insert_ids != observed.insert_ids {
                detail.push(format!(
                    "insert_ids expected {:?} got {:?}",
                    expected.insert_ids, observed.insert_ids
                ));
            }
            if expected.update_ids != observed.update_ids {
                detail.push(format!(
                    "update_ids expected {:?} got {:?}",
                    expected.update_ids, observed.update_ids
                ));
            }
            if expected.errors != observed.errors {
                detail.push(format!(
                    "errors expected {:?} got {:?}",
                    expected.errors, observed.errors
                ));
            }
            if expected.events != observed.events {
                detail.push(format!(
                    "events expected {:?} got {:?}",
                    expected.events, observed.events
                ));
            }
            if expected.checkpoint != observed.checkpoint {
                detail.push(format!(
                    "checkpoint expected {:?} got {:?}",
                    expected.checkpoint, observed.checkpoint
                ));
            }
            if expected.attachments_add != observed.attachments_add {
                detail.push(format!(
                    "attachments_add expected {:?} got {:?}",
                    expected.attachments_add, observed.attachments_add
                ));
            }
            if expected.attachments_remove != observed.attachments_remove {
                detail.push(format!(
                    "attachments_remove expected {:?} got {:?}",
                    expected.attachments_remove, observed.attachments_remove
                ));
            }
            if expected.attachments_update != observed.attachments_update {
                detail.push(format!(
                    "attachments_update expected {:?} got {:?}",
                    expected.attachments_update, observed.attachments_update
                ));
            }
            failures.push(format!("{}: {}", case.why, detail.join("; ")));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} committed cases disagree with upstream:\n{}",
        failures.len(),
        family.cases.len(),
        failures.join("\n")
    );
}

/// Every named rule in the family must be represented, so a shrunken family is noticed
/// rather than silently passing.
#[test]
fn the_family_still_covers_every_rule() {
    let family = load();
    for rule in [
        "fresh-insert",
        "update-existing",
        "update-without-previous-is-conflict",
        "update-conflict-stale-previous",
        "delete-existing",
        "revive-deleted-document-is-insert-event",
        "insert-already-deleted-document",
        "tombstone-for-unknown-document-inserts",
        "insert-attachment-without-data-is-510",
        "insert-with-attachment-data",
        "update-adds-attachment",
        "update-attachment-changed-digest",
        "update-removes-attachment",
        "delete-document-with-attachments-removes-them",
        "duplicate-ids-in-one-batch",
        "context-is-echoed",
        "empty-batch",
    ] {
        assert!(
            family.cases.iter().any(|case| case.why == rule),
            "the committed family no longer has a '{rule}' case"
        );
    }
    // And the generated sequences, which cover combinations the named cases do not.
    let generated = family
        .cases
        .iter()
        .filter(|case| case.why.starts_with("generated-sequence-"))
        .count();
    assert!(
        generated >= 20,
        "expected the generated sequences to remain, found {generated}"
    );
}

/// The resurrection rule, stated as its own assertion because it is the case that makes
/// event-reduce work and is easy to "fix" back to an UPDATE.
#[test]
fn a_revived_document_reports_insert_with_no_previous() {
    let family = load();
    let case = family
        .cases
        .iter()
        .find(|case| case.why == "revive-deleted-document-is-insert-event")
        .expect("the family must keep this case");
    let observed = observed_of(&family, case);
    let event = observed
        .events
        .iter()
        .find(|(_, operation, _, _)| operation == "INSERT")
        .expect("a resurrection must emit an INSERT event");
    assert!(
        !event.2,
        "a resurrection event must not carry a previous document"
    );
    assert_eq!(Operation::Insert.as_str(), "INSERT");
}
